import click
from click.core import ParameterSource
from click.testing import CliRunner

seen = {}

@click.command()
@click.option('--count', default=1)
@click.option('--name', prompt='Your name')
@click.pass_context
def hello(ctx, count, name):
    seen['count'] = ctx.get_parameter_source('count')
    seen['name'] = ctx.get_parameter_source('name')
    seen['help'] = ctx.get_parameter_source('_click_default_help')
    seen['value'] = name

res = CliRunner().invoke(hello, ['--count=3'], input='Click\n')
assert res.exit_code == 0, res.output
assert seen['count'] is ParameterSource.COMMANDLINE
assert seen['name'] is ParameterSource.PROMPT
assert seen['help'] is ParameterSource.DEFAULT
assert seen['value'] == 'Click'

