assert help_opt not in hello.params
assert [p.name for p in hello.params] == ['count', 'name']
res = CliRunner().invoke(hello, ['--count=3'], input='Click\n')
assert res.exit_code == 0, res.output
assert seen['params'] == ['count', 'name'], seen['params']

