import warnings
import click

@click.command()
@click.argument('foo')
@click.option('--foo', 'foo')
def cli(foo):
    pass

ctx = click.Context(cli)
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter('always')
    cli.get_params(ctx)
msgs = [str(x.message) for x in w]
assert any('unique name' in m for m in msgs), msgs

@click.command()
@click.option('--a', 'first')
@click.option('--a', 'second')
def cli2(first, second):
    pass

with warnings.catch_warnings(record=True) as w2:
    warnings.simplefilter('always')
    cli2.get_params(click.Context(cli2))
assert any('used more than once' in str(x.message) for x in w2)

import io
import sys
import click
from click.testing import CliRunner

try:
    CliRunner(capture='bogus')
except ValueError:
    pass
else:
    raise AssertionError('expected ValueError')

seen = {}

@click.command()
def cli():
    try:
        sys.stdout.fileno()
        seen['r'] = 'ok'
    except io.UnsupportedOperation:
        seen['r'] = 'unsupported'

CliRunner().invoke(cli)
assert seen['r'] == 'unsupported', seen

import click
from click.testing import CliRunner

@click.command()
def cli():
    raise click.ClickException('boom')

res = CliRunner().invoke(cli, [])
assert res.exit_code == 1
assert 'Error: boom' in res.stderr

try:
    cli.main([], 'cli', standalone_mode=False)
except click.ClickException as e:
    assert e.message == 'boom'
else:
    raise AssertionError('should have propagated')

@click.command()
def bad():
    raise click.UsageError('nope')

assert CliRunner().invoke(bad, []).exit_code == 2

import click
from click.testing import CliRunner

@click.command()
@click.option('--x', envvar='X_VAL', default='d')
def cli(x):
